using Microsoft.ML;
using Microsoft.ML.Data;
using Microsoft.ML.Transforms;

var builder = WebApplication.CreateBuilder(args);
var app = builder.Build();

// Train model on startup
var mlContext = new MLContext(seed: 42);

var csvPath = Path.Combine(app.Environment.ContentRootPath, "Data", "customers.csv");

var dataView = mlContext.Data.LoadFromTextFile<CustomerData>(csvPath, hasHeader: true, separatorChar: ',');

var labelMapping = new Dictionary<string, bool>
{
    { "Yes", true },
    { "No", false }
};

var pipeline = mlContext.Transforms.Conversion.MapValue(
        "Label", labelMapping, inputColumnName: nameof(CustomerData.Churned))
    .Append(mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(CustomerData.Region)))
    .Append(mlContext.Transforms.Concatenate("Features",
        nameof(CustomerData.Age),
        nameof(CustomerData.Income),
        nameof(CustomerData.PurchaseHistory),
        "RegionEncoded"))
    .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression());

var model = pipeline.Fit(dataView);
var predictionEngine = mlContext.Model.CreatePredictionEngine<CustomerData, ChurnPrediction>(model);

app.MapGet("/", () => "ChurnPredictor API");

app.MapPost("/predict", (PredictRequest request) =>
{
    var input = new CustomerData
    {
        Age = request.Age,
        Income = request.Income,
        Region = request.Region ?? "",
        PurchaseHistory = request.PurchaseHistory,
        Churned = ""
    };

    var prediction = predictionEngine.Predict(input);

    return Results.Json(new
    {
        willChurn = prediction.PredictedLabel,
        probability = prediction.Probability
    });
});

app.Run();

public class CustomerData
{
    [LoadColumn(0)]
    public float Age { get; set; }

    [LoadColumn(1)]
    public float Income { get; set; }

    [LoadColumn(2)]
    public string Region { get; set; } = string.Empty;

    [LoadColumn(3)]
    public float PurchaseHistory { get; set; }

    [LoadColumn(4)]
    public string Churned { get; set; } = string.Empty;
}

public class ChurnPrediction
{
    [ColumnName("PredictedLabel")]
    public bool PredictedLabel { get; set; }

    [ColumnName("Probability")]
    public float Probability { get; set; }
}

public record PredictRequest(float Age, float Income, string? Region, float PurchaseHistory);

